#include "termio/Capabilities.hpp"
#include "runtime/JsonValue.hpp"
#include <iostream>
int main(){using namespace batbox;Json cases;std::cin>>cases;Json all=Json::array();for(const auto& item:cases){Json trace=Json::array(),values=Json::array(),env=item.value("env",Json::object());termio::CapabilitiesServices services;
 services.environment={item.value("platform","linux"),[&](const std::string& key)->std::optional<std::string>{trace.push_back(Json::array({"env",key}));if(!env.contains(key)||env[key].is_null())return {};return env[key].get<std::string>();}};
 services.stdoutIsTTY=[&]{trace.push_back(Json::array({"tty"}));return item.value("tty",true);};services.terminalName=[&]()->std::optional<std::string>{trace.push_back(Json::array({"terminal"}));if(!item.contains("terminal"))return {};return item.at("terminal").get<std::string>();};
 services.coerceVersion=[&](const std::optional<std::string>& value)->std::optional<std::string>{trace.push_back(Json::array({"coerce",value?Json(*value):Json(nullptr)}));if(!item.contains("coerced")||item["coerced"].is_null()||item["coerced"]=="")return {};return item["coerced"].get<std::string>();};
 services.versionGte=[&](const std::string& version,const std::string& threshold){trace.push_back(Json::array({"gte",version,threshold}));return item.value("gte",false);};
 termio::CapabilitiesModule module(services);for(const auto& op:item.at("steps")){const auto kind=op.at("op").get<std::string>();if(kind=="env")env[op.at("key").get<std::string>()]=op.at("value");else if(kind=="set")module.setXtversionName(op.at("value"));else if(kind=="constant")values.push_back(module.syncOutputSupported());else{const auto name=op.at("name").get<std::string>();if(name=="isProgressReportingAvailable")values.push_back(module.isProgressReportingAvailable());else if(name=="isSynchronizedOutputSupported")values.push_back(module.isSynchronizedOutputSupported());else if(name=="isXtermJs")values.push_back(module.isXtermJs());else if(name=="supportsExtendedKeys")values.push_back(module.supportsExtendedKeys());else if(name=="hasCursorUpViewportYankBug")values.push_back(module.hasCursorUpViewportYankBug());}}
 all.push_back(Json{{"values",values},{"trace",trace}});}std::cout<<value::stringify(all)<<'\n';}
